  ($s$teamNames$s$, $s$["Red", "Blue", "Green", "Gold", "Purple", "Pink", "Mint", "Slate"]$s$::jsonb),
  ($s$scoring$s$, $s${"cardioPoints": 5, "habitDayPoints": 5, "levelSize": 50, "defaultWorkoutPoints": 5, "defaultThreshold": 200}$s$::jsonb),
  ($s$support$s$, $s${"email": "support@burnclub.com", "faqs": [{"q": "How do I change my workout schedule?", "a": "Head to Workouts \u2014 you can start any circuit any day, or build your own from the Exercise Library."}, {"q": "Can I pause my membership?", "a": "Yes \u2014 message your coach and they'll take care of it for you."}, {"q": "How do I connect a wearable?", "a": "Go to Profile \u2192 Connected Devices and tap Connect next to your device."}]}$s$::jsonb),
  ($s$copy$s$, $s${"tour": {"home": {"title": "Start Here", "body": "Home is your day at a glance \u2014 today's workout, your streak, and your daily habits. Most days this is the only screen you need."}, "workouts": {"title": "Every Workout", "body": "Browse the full circuit list and start any of them, any day. You can also build your own from the Exercise Library."}, "calendar": {"title": "Your Program", "body": "Your weeks are already laid out for you. Tap any day to see what's assigned and start it from there."}, "community": {"title": "The Club", "body": "See where you stand in this month's challenge, follow your team, and keep up with everyone else in the group."}, "progress": {"title": "Watch It Add Up", "body": "Your personal records, benchmark results, and every workout you've logged, all in one place."}, "contact": {"title": "Questions? Just Ask.", "body": "Message your coach any time and you'll get a real answer from a real person. You can replay this tour whenever you like from Profile \u2192 Help & Support.", "action": "Message Your Coach"}}, "programComplete": {"eyebrow": "Program summary", "title": "Your {weeks} weeks are up", "sub": "{program}, finished {date}.", "cta": "Message your coach", "note": "Ask about repeating this program, or what to move on to next."}}$s$::jsonb),
  ($s$habitPresets$s$, $s$[{"id": "steps-10k", "label": "10,000 Steps", "auto": "steps", "target": 10000}, {"id": "water-100oz", "label": "100oz Water"}, {"id": "outdoor-activity", "label": "Outdoor Activity"}, {"id": "pushups-25", "label": "25 Push-ups"}]$s$::jsonb),
  ($s$cardioTypes$s$, $s$[{"id": "Walk", "unitLabel": "Distance (mi)", "step": "0.1"}, {"id": "Run", "unitLabel": "Distance (mi)", "step": "0.1"}, {"id": "Bike", "unitLabel": "Distance (mi)", "step": "0.1"}, {"id": "Stair Stepper", "unitLabel": "Flights Climbed", "step": "1"}]$s$::jsonb),
  ($s$checkin$s$, $s${"title": "How are you today?", "sub": "Only you can see this.", "notePrompt": "Anything worth noting?", "notePlaceholder": "Sleep, soreness, stress, a win\u2026", "questions": [{"key": "mental", "label": "Mentally", "low": "Drained", "high": "Sharp"}, {"key": "physical", "label": "Physically", "low": "Beat up", "high": "Strong"}, {"key": "sleepHours", "label": "Hours slept", "low": "0", "high": "10", "unit": "hrs", "min": 0}], "sleepQuality": {"label": "How did you sleep?", "options": [{"value": "bad", "label": "Bad"}, {"value": "ok", "label": "OK"}, {"value": "good", "label": "Good"}, {"value": "great", "label": "Great"}]}}$s$::jsonb),
  ($s$notifications$s$, $s$[{"id": "workouts", "label": "Workout Reminders", "defaultOn": true}, {"id": "messages", "label": "New Messages", "defaultOn": true}, {"id": "community", "label": "Community Activity", "defaultOn": true}, {"id": "challenges", "label": "Challenge Updates", "defaultOn": true}, {"id": "weekly-summary", "label": "Weekly Progress Summary", "defaultOn": true}]$s$::jsonb),
